INSERT OR IGNORE INTO checklist_items (id, ref, section, position, title, description, owner, status, waiting_on, waiting_owner, done_at, done_by, created_at, created_by, updated_at, version) VALUES ('cl-002', 'A12', 'launch', 3, 'Listing reminders based on new photos', 'A listing stays live while the breeder adds new photos at least every four weeks. Reminder emails go at weeks 4 and 5, the listing goes offline at week 6 until a new photo is added, and it comes off the site at week 12 but stays in the breeder''s dashboard to relist. A banner in the portal lists the listings that need an update.', 'Claude', 'done', NULL, NULL, '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 1);
INSERT OR IGNORE INTO checklist_items (id, ref, section, position, title, description, owner, status, waiting_on, waiting_owner, done_at, done_by, created_at, created_by, updated_at, version) VALUES ('cl-003', 'A13', 'launch', 4, 'Breeder approval by reference', 'Sign-up asks for one reference who can confirm the breeder is real, such as an AKC representative, a local animal welfare council board member, another respected breeder or their veterinarian. The approval screen shows it, and approved breeders then list without review.', 'Claude', 'done', NULL, NULL, '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 1);
INSERT OR IGNORE INTO checklist_items (id, ref, section, position, title, description, owner, status, waiting_on, waiting_owner, done_at, done_by, created_at, created_by, updated_at, version) VALUES ('cl-004', 'A14', 'launch', 5, 'Photo standard and taking a listing offline for photos', 'The photo step and the listing terms say photos must be clear, sharp and show a healthy puppy. An admin can take a listing offline until the breeder uploads better photos, and a new upload brings it back.', 'Claude', 'done', NULL, NULL, '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 'launch plan', '2026-10-19T12:00:00Z', 1);
